cd /workspace && python3 - << 'EOF'
import importlib.util, json
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
# deep chain of `not` (1 wire depth per level) near the 64 limit
for depth in (58, 59, 60, 61, 62):
    node = {'op': 'contains', 'path': ['a']}
    for _ in range(depth):
        node = {'op': 'not', 'arg': node}
    req = {'services': ['a'], 'rules': [{'action': 'allow', 'when': node}], 'queries': [['a']]}
    out = json.loads(m.process(json.dumps(req).encode()))
    print('not-depth', depth, '->', out.get('ok'), out.get('error', ''),
          (len(out['dfa']['next']) if out.get('ok') else ''))
EOF
